CREATE OR REPLACE FUNCTION result_data_private.schema_supported_v1()
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
 select ((select pg_get_constraintdef(k.oid) from pg_constraint k where k.conrelid='turn_private.text_policies'::regclass and k.conname='text_policies_context_mode_check') is not distinct from 'CHECK ((context_mode = ANY (ARRAY[''current_input_v1''::text, ''task_history_v1''::text, ''knowledge_intent_v1''::text, ''qa_session_history_v1''::text])))') and ((select pg_get_constraintdef(k.oid) from pg_constraint k where k.conrelid='turn_private.service_task_turns'::regclass and k.conname='service_task_turns_relationship_check') is not distinct from 'CHECK ((relationship = ANY (ARRAY[''new_goal''::text, ''clarification''::text, ''repair''::text, ''qa_followup''::text, ''qa_correction''::text])))') and turn_private.directions_schema_members_v1() and profile_data_private.schema_v1() and result_data_private.infrastructure_supported_v1() and result_data_private.digest_v1((select coalesce(jsonb_agg(jsonb_build_object('relation',n.nspname||'.'||c.relname,'columns',(select jsonb_agg(jsonb_build_array(a.attname,format_type(a.atttypid,a.atttypmod),a.attnotnull) order by a.attnum) from pg_attribute a where a.attrelid=c.oid and a.attnum>0 and not a.attisdropped),'constraints',(select jsonb_agg(case when k.conrelid='turn_private.text_policies'::regclass and k.conname='text_policies_context_mode_check' then 'CHECK ((context_mode = ANY (ARRAY[''current_input_v1''::text, ''task_history_v1''::text, ''knowledge_intent_v1''::text])))' when k.conrelid='turn_private.service_task_turns'::regclass and k.conname='service_task_turns_relationship_check' then 'CHECK ((relationship = ANY (ARRAY[''new_goal''::text, ''clarification''::text, ''repair''::text])))' else pg_get_constraintdef(k.oid) end order by k.conname) from pg_constraint k where k.conrelid=c.oid)) order by n.nspname,c.relname),'[]'::jsonb) from pg_class c join pg_namespace n on n.oid=c.relnamespace where c.relkind='r' and n.nspname not in('pg_catalog','information_schema','extensions','auth','result_data_private','storage','realtime','_realtime','vault','supabase_functions','supabase_migrations'))::text)='0ec0fcfc206909a38756272a65a877c6ab857c00fd114178d135837da951c73a'
$function$;
